// Reproduce the difference in how DevTools vs Lighthouse capture OOPIF network requests.
// This script uses chrome-remote-interface to attach to main and iframe targets.

const http = require('http');
const path = require('path');
const fs = require('fs');
const CDP = require('chrome-remote-interface');

// 1) Spin up a simple HTTP server serving an HTML page with a cross-origin iframe.
const html = `<!DOCTYPE html>
<html>
  <body>
    <h1>Main page</h1>
    <!-- This iframe src must be a different origin to trigger OOPIF -->
    <iframe src="https://example.com" width="600" height="400"></iframe>
  </body>
</html>`;
const server = http.createServer((req, res) => {
  res.writeHead(200, {'Content-Type': 'text/html'});
  res.end(html);
});

server.listen(8080, async () => {
  console.log('Server listening at http://localhost:8080');
  console.log('Start Chrome with --remote-debugging-port=9222');

  // 2) Connect to Chrome DevTools Protocol
  const client = await CDP({port: 9222});
  const {Network, Page, Target} = client;

  // Enable network on the main session
  await Network.enable();
  Network.requestWillBeSent(event => {
    console.log('[main target] ', event.request.url);
  });

  // Tell Chrome to notify us about new targets (OOPIFs)
  await Target.setDiscoverTargets({discover: true});

  // When a new target is created, attach and enable Network on that session
  Target.targetCreated(async ({targetInfo}) => {
    if (targetInfo.type === 'iframe') {
      console.log(`Discovered iframe target: ${targetInfo.targetId}`);
      const attachRes = await Target.attachToTarget({
        targetId: targetInfo.targetId,
        flatten: true,
      });
      const sessionId = attachRes.sessionId;
      console.log(`Attached to iframe session: ${sessionId}`);

      // Create a client for the iframe session
      const iframeClient = client.session(sessionId);
      await iframeClient.Network.enable();
      iframeClient.Network.requestWillBeSent(ev => {
        console.log('[iframe target] ', ev.request.url);
      });
    }
  });

  // 3) Navigate the main page
  await Page.enable();
  await Page.navigate({url: 'http://localhost:8080'});
  await Page.loadEventFired();

  console.log('Navigation complete. Watch console for both main + iframe URLs.');
});
